mapper.select:
SELECT SUM(FIRST_CAL.COUNT) AS COUNT FROM(
SELECT SHOP_TYPE, COUNT(DISTINCT SHOP_ID) AS COUNT FROM CBCI_ACCOUNT CA INNER JOIN CBCI_USER CU WHERE CA.USER_NO = CU.USER_NO AND (CA.DEL_YN != 'Y' OR CA.DEL_YN IS NULL OR CA.LOGIN_LOCK != 'Y') AND (CU.WITHDRAW_YN != 'Y' OR CU.WITHDRAW_YN IS NULL)
AND CA.INPUT_DATETIME < #{fromDate}
GROUP BY SHOP_TYPE ORDER BY SHOP_TYPE , SHOP_ID
)FIRST_CAL

SELECT 
	COUNT(*)
FROM CBCI_ACCOUNT

	WHERE INPUT_DATETIME <= #{toDate}


	WHERE INPUT_DATETIME <= #{excelFromDate}


	AND SHOP_TYPE=#{shopType}
